from PyQt5.QtCore import Qt, QModelIndex, QAbstractListModel, pyqtSignal

class ConversationModel(QAbstractListModel):
    message_sending_requested = pyqtSignal(str)
    _role_names = {
        Qt.UserRole + 1: b'time',
        Qt.UserRole + 2: b'sender',
        Qt.UserRole + 3: b'contents'
    }

    def __init__(self, channel_name, messages=None):
        super().__init__()
        self._channel = channel_name
        self._messages = messages if messages else []

    @property
    def channel(self):
        return self._channel

    def rowCount(self, parent=QModelIndex()):
        return len(self._messages)

    def roleNames(self):
        return self._role_names

    def send_message(self, contents):
        self.message_sending_requested.emit(contents)

    def add_incoming_message(self, message):
        self.beginInsertRows(QModelIndex(), len(self._messages), len(self._messages))
        self._messages.append(message)
        self.endInsertRows()

    def data(self, index, role=Qt.DisplayRole):
        if not index.isValid() or not (0 <= index.row() < len(self._messages)):
            return None
        message = self._messages[index.row()]
        if role == ItemRole.TIME:
            return message.time
        elif role == ItemRole.SENDER:
            return message.sender
        elif role == ItemRole.CONTENTS:
            return message.contents
        return None
