Converting an array into a self-balancing Binary Search Tree (BST) and maintaining its balance for operations can be achieved with a data structure known as the AVL tree. AVL tree maintains balance by ensuring that the difference in the height of the left and right subtrees is at most 1.

Here's a Python solution using an AVL tree concept:

```python
class Node:
    def __init__(self, key):
        self.key  = key
        self.left = None
        self.right = None
        self.height = 1

class AVL_Tree:
    def __init__(self):
        self.root = None

    def insert(self, root, key):
        if not root:
            return Node(key)
        elif key < root.key:
            root.left = self.insert(root.left, key)
        else:
            root.right = self.insert(root.right, key)

        root.height = 1 + max(self.getHeight(root.left),
                              self.getHeight(root.right))

        balance = self.getBalance(root)

        if balance > 1:
            if key < root.left.key:
                return self.rightRotate(root)
            else:
                root.left = self.leftRotate(root.left)
                return self.rightRotate(root)
        if balance < -1:
            if key > root.right.key:
                return self.leftRotate(root)
            else:
                root.right = self.rightRotate(root.right)
                return self.leftRotate(root)
        return root

    def leftRotate(self, z):
        y = z.right
        T2 = y.left
        y.left = z
        z.right = T2
        z.height = 1 + max(self.getHeight(z.left),
                         self.getHeight(z.right))
        y.height = 1 + max(self.getHeight(y.left),
                         self.getHeight(y.right))
        return y

    def rightRotate(self, y):
        x = y.left
        T3 = x.right
        x.right = y
        y.left = T3
        y.height = 1 + max(self.getHeight(y.left),
                         self.getHeight(y.right))
        x.height = 1 + max(self.getHeight(x.left),
                         self.getHeight(x.right))
        return x

    def getHeight(self, root):
        if not root:
            return 0
        return root.height

    def getBalance(self, root):
        if not root:
            return 0
        return self.getHeight(root.left) - self.getHeight(root.right)

    def arrayToAVL(self, arr, start, end):
        if start > end:
            return None
        mid = (start + end) // 2
        node = self.insert(self.root, arr[mid])
        node.left = self.arrayToAVL(arr, start, mid - 1)
        node.right = self.arrayToAVL(arr, mid + 1, end)
        return node
```

This script creates an AVL tree from an array 'arr' from index 'start' to 'end'. Since it uses binary search, the array must be sorted in ascending order before being used.

