class TaskListResource(Resource):
    def get(self):
        status_filter = request.args.get('status')
        if status_filter:
            filtered_tasks = [task for task in tasks if task['status'] == status_filter]
            return {'tasks': filtered_tasks}
        return {'tasks': tasks}

