    rr := requestReturn{url: url}
    var resp *http.Response
    defer func() {
        if resp != nil {
            resp.Body.Close()
        }
        ok <- rr
        <-threadLimit
    }()
    ...
}
```

By moving the `defer` statement before the `return` statements, you ensure that the `resp.Body.Close()` and `ok <- rr` statements are executed even if there are early returns. This will properly free up the resources and maintain the correct concurrency control.

def bubble_sort(arr):
    # Get the length of the array
    n = len(arr)

    # Traverse through all elements in the array
    for i in range(n):

        # Last i elements are already sorted, so we skip them
        for j in range(0, n - i - 1):

            # Swap if current element is greater than next one
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]

    return arr

