void initSnake()
{
    head = (Snake *)malloc(sizeof(Snake));
    head->x = mapWidth / 2 - 1;
    head->y = mapHeight / 2;
    head->next = NULL;
    addNode(head->x + 1, head->y);
    addNode(head->x + 2, head->y);
    tail = head->next->next;
}
void addNode(int x, int y)
{
    Snake *node = (Snake *)malloc(sizeof(Snake));
    node->x = x;
    node->y = y;
    node->next = NULL;
    tail->next = node;
    tail = node;
}
void moveSnake(int dx, int dy)
{
    int x = head->x + dx;
    int y = head->y + dy;
    if (isCollide(x, y))
        gameOver();
    if (map[y][x] == 1)
    {
        createFood();
        score++;
        addNode(x, y);
    }
    else
    {
        map[tail->y][tail->x] = 0;
        tail->x = x;
        tail->y = y;
        head = head->next;
        tail = tail->next;
    }
    head->x = x;
    head->y = y;
    map[y][x] = 2;
}
