        if country_region not in parsed_data:
            parsed_data[country_region] = {}
        if province_state not in parsed_data[country_region]:
            parsed_data[country_region][province_state] = {
                'confirmed': 0,
                'deaths': 0,
                'recovered': 0
            }
        parsed_data[country_region][province_state]['confirmed'] += entry['confirmed']
        parsed_data[country_region][province_state]['deaths'] += entry['deaths']
        parsed_data[country_region][province_state]['recovered'] += entry['recovered']
