def recursive_lookup(dictionary, key_path):
    if not dictionary or not key_path:
        return None
    if isinstance(key_path, str):
        key_path = key_path.split(".")
    if key_path[0] in dictionary:
        if isinstance(dictionary[key_path[0]], dict):
            return recursive_lookup(dictionary[key_path[0]], key_path[1:])
        elif len(key_path) == 1:
            return dictionary[key_path[0]]
    return None
```

