    if namespace_str == "":
        return {}
    variable_value_pairs = [var_value_pair.strip() for var_value_pair in namespace_str.split(',')]
    namespace = {}
    for var_value_pair in variable_value_pairs:
        var_name, var_value = var_value_pair.split('=')
        var_value = eval(var_value)
        namespace = _generate_namespace_recursive(var_name, var_value, namespace)

