```cpp
#include <vector>

std::vector<int> intersectSortedArrays(std::vector<int>& array1, std::vector<int>& array2) {
    std::vector<int> intersection;
    int i = 0;
    int j = 0;
    while(i < array1.size() && j < array2.size()) {
        if (array1[i] < array2[j]) {
            i++;
        } else if (array2[j] < array1[i]) {
            j++;
