```

Function to check balance (difference between left and right children heights):

```python
def get_balance(node):
    if node is None:
        return 0
    return height(node.left) - height(node.right)
```

Function to right rotate:

```python
def right_rotate(node_y):
    node_x = node_y.left
    T2 = node_x.right

    node_x.right = node_y
    node_y.left = T2

    node_y.height = 1 + max(height(node_y.left), height(node_y.right))
    node_x.height = 1 + max(height(node_x.left), height(node_x.right))

    return node_x
```

Function to left rotate:

```python
def left_rotate(node_x):
    node_y = node_x.right
    T2 = node_y.left

    node_y.left = node_x
    node_x.right = T2

    node_x.height = 1 + max(height(node_x.left), height(node_x.right))
    node_y.height = 1 + max(height(node_y.left), height(node_y.right))

    return node_y
```

Function to insert a node and keep the tree balanced via AVL rotations:

```python
def insert_node(node, key):
    if not node:
        return Node(key)
    elif key < node.val:
        node.left = insert_node(node.left, key)
    else: 
        node.right = insert_node(node.right, key)

    node.height = 1 + max(height(node.left), height(node.right))

    balance = get_balance(node)

    if balance > 1:
        if key < node.left.val:
            return right_rotate(node)
        else:
            node.left = left_rotate(node.left)
            return right_rotate(node)

    if balance < -1:
        if key > node.right.val:
            return left_rotate(node)
        else:
            node.right = right_rotate(node.right)
            return left_rotate(node)

    return node
```

Function to calculate diameter (longest path between nodes):

```python
def diameter(node):
    if node is None:
        return 0

    lheight = height(node.left)
    rheight = height(node.right)

    ldiameter = diameter(node.left)
    rdiameter = diameter(node.right)

    return max(lheight + rheight + 1, max(ldiameter, rdiameter))
```

